import sys, math

for line in sys.stdin:
    line = line.strip()
    if not line:
        continue
    a, b = map(int, line.split())
    g = math.gcd(a, b)
    a //= g
    b //= g
    if b == 1:
        print(a)
    else:
        print(f"{a}/{b}")

