import sys

MAXN = 1000000
sieve = bytearray([1]) * (MAXN + 3)
sieve[0] = sieve[1] = 0
i = 2
while i * i <= MAXN + 2:
    if sieve[i]:
        for j in range(i * i, MAXN + 3, i):
            sieve[j] = 0
    i += 1

for line in sys.stdin:
    line = line.strip()
    if not line:
        continue
    a, b = map(int, line.split())
    count = 0
    for p in range(a, b - 1):
        if sieve[p] and sieve[p + 2]:
            count += 1
    print(count)

