import sys

for line in sys.stdin:
    line = line.strip()
    if not line:
        continue
    a, b = map(int, line.split())
    count = 0
    for n in range(a, b + 1):
        digits = str(n)
        d = len(digits)
        if sum(int(c) ** d for c in digits) == n:
            count += 1
    print(count)

